'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=location.hash.slice(1)||sessionStorage.getItem('dpm-token')||'';
if(location.hash){sessionStorage.setItem('dpm-token',token);history.replaceState(null,'',location.pathname);}
let state={tracks:[],colors:{},revision:-1,counts:{},reviewed:0},view='library',stageFilter=null,selected=new Set(),focused=null,sort='name',ascending=true,manual=null,manualIndex=0,studied=[],queue=[],trainingId=null,bpmIds=[],transitionSource=null,busy=false;
let toastTimer,pollTimer,lastTrainingId=null,lastRowId=null,stopped=false;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,error?9000:4000);}
async function api(path,data){const response=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'X-DPM-Token':token,...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Operation failed');return result;}
async function action(path,data={}){if(busy)return null;busy=true;try{const result=await api(path,data);await refresh();return result;}catch(error){toast(error.message,true);return null;}finally{busy=false;}}
const track=id=>state.tracks.find(t=>t.id===id);
const palette={'Gathering':'#b388ff','Confidence':'#6eb6ff','Peak Hype':'#ff4fa3','Chaos':'#ff5a1f','Locked In':'#3dff9a','Sketch Hours':'#2ee0d4','Rebirth':'#ffb020','Sunrise':'#ffe14a'};
const color=stage=>palette[stage]||state.colors[stage]||'#b388ff';
const chip=stage=>`<span class="category-chip" style="--stage:${color(stage)}">${esc(stage)}</span>`;
const bpm=t=>t?.bpm==null||!Number.isFinite(Number(t.bpm))?'—':Number(t.bpm).toFixed(2).replace(/\.00$/,'').replace(/(\.\d)0$/,'$1');
const sourceLabel=t=>t.bpm_source==='manual'?'YOUR CORRECTION':t.bpm_source==='file_tag'?(t.tempo_review_required?'TAG · CHECK':'FILE TAG'):t.bpm_source==='range_estimate'?'RANGE · CHECK':'ESTIMATE · CHECK';
function usable(){return state.tracks.filter(t=>Number.isFinite(t.duration_seconds)&&t.duration_seconds>=state.minimum&&t.duration_seconds<=state.maximum);}
function visible(){const query=$('#search').value.toLowerCase(),tempo=$('#tempo-filter').value;return usable().filter(t=>(!stageFilter||t.current_stage===stageFilter)&&(!query||t.name.toLowerCase().includes(query)||t.path.toLowerCase().includes(query))&&(tempo==='all'||tempo==='review'&&t.tempo_review_required||t.bpm_source===tempo)).sort((a,b)=>{const n=sort==='bpm'?((a.bpm??-1)-(b.bpm??-1)):a.name.localeCompare(b.name);return ascending?n:-n;});}
function setView(name){view=name;$$('.workspace-view').forEach(el=>el.hidden=el.id!==name+'-view');$$('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===name));if(name==='manual')loadManual();if(name==='training')renderTraining();if(name==='settings')populateSettings();if(name==='sets')loadSets();renderRail();}
function renderRail(){const stages=Object.keys(state.colors);$('#stage-rail').innerHTML=stages.map((stage,i)=>`<button class="stage-button ${(view==='manual'?manualIndex===i:stageFilter===stage)?'selected':''}" data-stage="${esc(stage)}" style="--stage:${color(stage)}"><span class="stage-number">${String(i+1).padStart(2,'0')}</span><span class="stage-name">${esc(stage)}</span><span class="stage-count">${state.counts[stage]??0}</span></button>`).join('');if(view==='manual')applyLens();}
function renderSummary(){$('#eligible-total').textContent=state.eligible||0;$('#reviewed-total').textContent=state.reviewed||0;$('#reviewed-badge').textContent=state.reviewed||0;$('#tempo-review-total').textContent=usable().filter(t=>t.tempo_review_required).length;$('#library-title').innerHTML=`${esc(stageFilter||'The collection')} <span id="visible-count">${visible().length}</span>`;$('#filter-kicker').textContent=stageFilter?'THE NIGHT ARC / '+stageFilter.toUpperCase():'ALL EIGHT STAGES';}
function renderRows(){const rows=visible();$('#track-rows').innerHTML=rows.map(t=>`<tr data-id="${esc(t.id)}" class="${selected.has(t.id)?'selected':''}" tabindex="0"><td class="check-col"><input type="checkbox" data-check="${esc(t.id)}" ${selected.has(t.id)?'checked':''} aria-label="Select ${esc(t.name)}"></td><td><span class="track-name"><span class="song-stage" style="--stage:${color(t.current_stage)}" title="Stage number">${t.stage_number||Object.keys(palette).indexOf(t.current_stage)+1}</span> ${esc(t.name)}</span><span class="track-sub">${esc(t.manual_stage?'YOUR PLACEMENT':t.missing?'DRIVE UNAVAILABLE':t.learned_stage!==t.suggested_stage?'LEARNED PLACEMENT':'')||' '}</span></td><td>${chip(t.current_stage)}</td><td class="bpm-cell"><button class="bpm-number" data-bpm="${esc(t.id)}" title="${esc(t.tempo_note||'Correct BPM')}">${bpm(t)}</button><span class="source ${t.tempo_review_required?'warning':''} ${t.bpm_source==='manual'?'manual':''}">${sourceLabel(t)}</span></td><td class="key-code">${esc(t.camelot||'—')}</td><td class="play-col"><button class="library-add-button" data-library-add="${esc(t.id)}">Add to set</button><button class="table-play" data-play="${esc(t.id)}" aria-label="Play ${esc(t.name)}">${state.playing===t.id?'■':'▶'}</button></td></tr>`).join('');$('#empty').hidden=rows.length>0;$('#library-table').hidden=rows.length===0;if(!rows.length&&state.tracks.length){$('#empty h3').textContent='No tracks in this view.';$('#empty p').textContent='Try another stage, BPM filter or search.';$('#empty-scan').hidden=true;}else{$('#empty h3').textContent='Your next dimension starts here.';$('#empty p').textContent='Scan a music folder to bring your tracks into the matrix.';$('#empty-scan').hidden=false;}$('#select-all').checked=rows.length>0&&rows.every(t=>selected.has(t.id));renderBatch();renderSummary();renderLibrarySetTargets();if($('#add-visible-to-set')){$('#add-visible-to-set').disabled=!rows.length;$('#add-visible-to-set').textContent=`Add visible to set (${rows.length})`;}}
function renderBatch(){$('#batch-bar').hidden=selected.size===0;$('#selection-count').textContent=`${selected.size} SELECTED`;$('#undo').disabled=!state.can_undo;}
function renderPlayer(){const p=state.playback||{},t=track(p.id)||track(state.playing)||track(focused);$('#player-name').onclick=t?()=>detail(t.id):null;$('#player-name').textContent=t?.name||'Select a track to listen';$('#player-meta').textContent=t?`${bpm(t)} BPM / ${t.camelot||'KEY —'} / ${p.state||'READY'}`:'Listen first. Then decide where it belongs.';$('#player-stage').textContent=t?`${t.stage_number||Object.keys(palette).indexOf(t.current_stage)+1} · ${t.current_stage}`:'';$('#player-stage').style.color=t?color(t.current_stage):'';$('#player-stop').disabled=!p.id;$('#player-play').textContent=p.state==='playing'?'Ⅱ':'▶';if(!seeking){$('#audio-seek').max=p.duration||0;$('#audio-seek').value=p.position||0;$('#elapsed').textContent=clock(p.position);$('#audio-duration').textContent=clock(p.duration);}$('#audio-seek').disabled=!p.seekable;}
function clock(n){n=Math.max(0,Math.floor(n||0));return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
let seeking=false;
let refreshing=false;
async function refresh(){if(refreshing||stopped)return;refreshing=true;const epoch=profileEpoch;try{const next=await api('state?revision='+state.revision);if(stopped||epoch!==profileEpoch)return;const changed=next.revision!==state.revision,playChanged=next.playing!==state.playing;const rows=next.tracks||state.tracks;state={...state,...next,tracks:rows};$('#status').textContent=state.status;$('#scan-badge').hidden=!state.scan_running;$('#cancel-scan').hidden=!state.scan_running;$('#scan').disabled=state.scan_running||state.busy;$('#refresh-tags').disabled=state.scan_running||state.busy;$('#connection').textContent='Local companion · v'+state.version;if(changed){const old=$('#batch-category').value;$('#batch-category').innerHTML=Object.keys(state.colors).map(name=>`<option>${esc(name)}</option>`).join('');if(old)$('#batch-category').value=old;selected=new Set([...selected].filter(id=>track(id)));renderRail();renderRows();if(view==='training')renderTraining();}else if(playChanged&&view==='library'){renderRows();}renderPlayer();renderJob();renderProfileControls();}catch(error){$('#status').textContent=error.message;}finally{refreshing=false;}}
async function play(id){if(!id)return;focused=id;const played=await action('play',{id});renderPlayer();if(played&&view==='sets'&&activeSet)renderSetInspector();}
function openBpm(ids){bpmIds=ids;const first=track(ids[0]);if(!first)return;$('#bpm-context').textContent=ids.length===1?`${first.name}\n${first.tempo_note||''} Tag: ${first.tag_bpm??'—'} · Detector: ${first.measured_bpm??first.analysis_bpm??'—'}`:`Apply one BPM to ${ids.length} selected tracks.`;$('#bpm-value').value=first.bpm??'';$('#bpm-dialog').showModal();$('#bpm-value').focus();$('#bpm-value').select();}
function detail(id){focused=id;renderPlayer();const t=track(id);if(!t)return;const scores=t.scores||{};$('#details-content').innerHTML=`<p class="kicker">TRACK / INSIDE THE SIGNAL</p><h2 class="detail-heading">${esc(t.name)}</h2>${chip(t.current_stage)}<div class="detail-actions"><button data-play="${esc(id)}" class="primary">▶ Listen</button><button data-next="${esc(id)}" class="secondary">Next track ↗</button><button data-library-add="${esc(id)}" class="secondary">Add to set</button></div><div class="detail-grid"><div class="detail-card"><small>BPM · ${sourceLabel(t)}</small><strong>${bpm(t)}</strong></div><div class="detail-card"><small>KEY</small><strong>${esc(t.camelot||'—')}</strong></div></div><p class="quiet">${esc(t.tempo_note||'Check the estimated tempo by ear.')}</p><div class="detail-actions"><button data-recheck="${esc(id)}" class="small-secondary">Recheck audio BPM</button><button data-bpm="${esc(id)}" class="small-secondary">Correct BPM</button><button data-factor=".5" data-track="${esc(id)}" class="small-secondary">× ½</button><button data-factor="2" data-track="${esc(id)}" class="small-secondary">× 2</button></div><div class="detail-label">PLACEMENT</div><p class="quiet">Original: ${esc(t.suggested_stage)}<br>Learned: ${esc(t.learned_stage)}<br>Your label: ${esc(t.manual_stage||'Not labeled')}</p><select id="detail-category" aria-label="Manual category">${Object.keys(state.colors).map(s=>`<option ${s===t.current_stage?'selected':''}>${esc(s)}</option>`).join('')}</select><button data-detail-assign="${esc(id)}" class="small-primary">Save category</button><div class="detail-label">DPM PROXIES</div>${Object.entries(scores).filter(([k])=>!['Intro Length','Outro Length'].includes(k)).map(([name,value])=>`<div class="score-row"><span>${esc(name)}</span><div class="score-meter"><i style="width:${Math.max(0,Math.min(100,(value||0)*10))}%"></i></div><span>${value==null?'—':Number(value).toFixed(1)}</span></div>`).join('')}<p class="quiet">Musical proxies, not calibrated probabilities. “Vocal Presence” can respond to instruments. Your ears decide.</p><details><summary>Analysis & provenance</summary><p>Tag BPM: ${esc(t.tag_bpm??'—')}<br>Estimated BPM: ${esc(t.measured_bpm??'—')}<br>Alternatives: ${esc((t.tempo_candidates||[]).join(' / '))}<br>Method: ${esc(t.score_version||'legacy')}<br>Reference: ${esc(t.reference_size||'—')} tracks</p><pre>${esc(JSON.stringify(t.raw_features||{},null,2))}</pre></details>`;if(!$('#details').open)$('#details').showModal();}
async function newBatch(){const result=await action('batch');if(!result)return;queue=result.ids;trainingId=queue[0]||null;renderTraining();}
function renderTraining(){queue=queue.filter(id=>track(id)&&!track(id).manual_stage);if(!queue.includes(trainingId))trainingId=queue[0]||null;const current=track(trainingId);if(!current){$('#training-content').innerHTML=`<div class="empty"><span>◈</span><h3>${queue.length?'Choose a track.':'Make the matrix sound like you.'}</h3><p>Start a batch, listen, and place each record into a stage.<br>Saved placements immediately refresh the collection.</p><button class="primary" data-new-batch>Start a 20-track batch</button></div>`;return;}$('#training-content').innerHTML=`<div class="training-layout"><div class="training-queue">${queue.map((id,i)=>{const t=track(id);return `<button data-train-track="${esc(id)}" class="queue-track ${id===trainingId?'active':''}"><span>${String(i+1).padStart(2,'0')} / ${esc(t.name)}</span><small>${bpm(t)} BPM · ${esc(t.camelot||'—')} · ${sourceLabel(t)}</small></button>`;}).join('')}</div><div class="training-card"><p class="kicker">${queue.length} LEFT IN THIS BATCH</p><h3>${esc(current.name)}</h3><div class="detail-actions"><button data-play="${esc(current.id)}" class="primary">▶ Listen</button><button data-bpm="${esc(current.id)}" class="secondary">${bpm(current)} BPM ↗</button></div><p class="quiet">Where would you play this? Choose by ear.<br>Model suggestions are kept out of the way.</p><div class="category-grid">${Object.keys(state.colors).map(s=>`<button data-train-stage="${esc(s)}" style="--stage:${color(s)}">${esc(s)}</button>`).join('')}</div><button id="train-undo" class="text-button">Undo last placement</button></div></div>`;}
async function loadManual(){if(!manual){try{manual=await api('manual');studied=(await api('study_progress',{})).ids||[];$('#dimension-lens').innerHTML='<option value="">All dimensions</option>'+manual.dimensions.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');}catch(error){toast(error.message,true);return;}}renderManual();}
function renderManual(){if(!manual)return;const s=manual.stages[manualIndex];$('#study-count').textContent=`${studied.length} / 8 studied`;$('#manual-content').style.setProperty('--stage',color(s.name));$('#manual-content').innerHTML=`<p class="kicker">STAGE ${esc(s.n)} / THE NIGHT ARC</p><h2>${esc(s.name)}</h2><span class="window">${esc(s.window)}</span>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<h3>The floor</h3><p>${esc(s.floor)} ${esc(s.crowd)}</p><h3>Frequency</h3><p>${esc(s.frequency)}</p><h3>Arrangement blueprint</h3><div class="arrangement">${s.arrangement.map(a=>`<div>${esc(a.label)}<span>${esc(a.detail)}</span></div>`).join('')}</div><h3>Play toward</h3><ul>${s.play.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><h3>Leave in the crate</h3><ul>${s.avoid.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><h3>Dimensions</h3><p>High: ${esc(s.high.join(', '))}<br>Low: ${esc(s.low.join(', '))}</p><h3>Mix note</h3><p>${esc(s.mix)}</p><p class="quiet">Creative programming guidance; arrangement examples are not extracted bar counts. Automated emotion, vocal and recovery values remain experimental proxies.</p><div class="dialog-actions"><button class="primary" id="toggle-studied">${studied.includes(s.id)?'✓ Studied · unmark':'Mark as studied'}</button><button id="manual-prev" class="secondary">← Previous</button><button id="manual-next" class="secondary">Next →</button></div>`;renderRail();}
function applyLens(){if(!manual)return;const selectedLens=manual.dimensions.find(d=>d.id===$('#dimension-lens').value);$$('.stage-button').forEach((button,i)=>button.classList.toggle('dim',!!selectedLens&&!selectedLens.stages.includes(manual.stages[i].id)));}
async function openTransitions(id){transitionSource=id;const t=track(id);$('#transition-title').textContent='From '+t.name;$('#transition-dialog').showModal();await refreshTransitions();}
async function refreshTransitions(){const result=await action('transitions',{id:transitionSource,delta:Number($('#delta').value),weights:{harmonic:Number($('#weight-h').value),energy:Number($('#weight-e').value),bpm:Number($('#weight-b').value)},half_double:$('#half-double').checked});if(!result)return;$('#transition-results').innerHTML=result.rows.map(row=>{const t=track(row.id),parts=row.components;return `<div class="transition-row"><div><b>${esc(t.name)}</b><small>${bpm(t)} BPM · ${esc(t.camelot||'—')} · ${esc(t.current_stage)}</small><small>Harmony ${parts.harmonic??'—'} / energy ${parts.energy==null?'—':parts.energy.toFixed(0)} / BPM ${parts.bpm==null?'—':parts.bpm.toFixed(0)}${row.half_double_used?' · half/double used':''}</small></div><span class="transition-score">${row.score??'—'}</span><small class="transition-coverage">${Math.round(row.coverage*100)}% inputs</small><button data-play="${esc(t.id)}" class="table-play" aria-label="Play ${esc(t.name)}">▶</button></div>`;}).join('')||'<p class="quiet">No other eligible tracks.</p>';}
// Event delegation keeps library rendering cheap and avoids per-row listeners.
document.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.close){$('#'+target.dataset.close).close();return;}if(target.dataset.view){setView(target.dataset.view);return;}if(target.dataset.stage){const index=Object.keys(state.colors).indexOf(target.dataset.stage);if(view==='manual'){manualIndex=index;renderManual();}else{stageFilter=target.dataset.stage;selected.clear();setView('library');renderRows();}return;}if(target.dataset.play){await play(target.dataset.play);return;}if(target.dataset.recheck){await recheck([target.dataset.recheck]);return;}if(target.dataset.bpm){openBpm([target.dataset.bpm]);return;}if(target.dataset.next){await openTransitions(target.dataset.next);return;}if(target.dataset.factor){await action('tempo',{ids:[target.dataset.track],factor:Number(target.dataset.factor)});detail(target.dataset.track);return;}if(target.dataset.detailAssign){await action('labels',{ids:[target.dataset.detailAssign],stage:$('#detail-category').value});detail(target.dataset.detailAssign);return;}if(target.dataset.trainTrack){trainingId=target.dataset.trainTrack;focused=trainingId;renderTraining();renderPlayer();return;}if(target.dataset.trainStage){const assignedId=trainingId;const result=await action('labels',{ids:[assignedId],stage:target.dataset.trainStage});if(result){lastTrainingId=assignedId;queue=queue.filter(id=>id!==assignedId);trainingId=queue[0]||null;renderTraining();if(!queue.length){setView('library');toast('Batch saved. Library placements have been updated.');}}return;}if(target.hasAttribute('data-new-batch')){await newBatch();return;}if(target.dataset.action){$('#more-menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');const name=target.dataset.action;if(name==='reload')await action('reload');if(name==='drive')await action('scan',{drive23:true});if(name==='import')await action('import_crates');if(name==='export')await action('export');if(name==='install'){if(confirm('Install the last preview into Serato? Close Serato first. Existing DPM-5D crates will be backed up.'))await action('install_crates',{confirmed:true});}if(name==='settings')setView('settings');if(name==='tags')await action('refresh_tags');if(name==='quit'&&confirm('Quit DPM'+(state.scan_running?' and stop the scan':'')+'?')){stopped=true;clearInterval(pollTimer);const result=await action('quit');if(result){document.body.innerHTML='<main style="margin:12vh auto;max-width:600px"><p class="kicker">SIGNAL CLOSED</p><h1>Until the next<br><em>dimension.</em></h1><p>DPM is closing. Open Launch.command to return.</p></main>';}}return;}switch(target.id){case 'recheck-bpm':await recheck(selected.size?[...selected]:visible().map(t=>t.id));break;case 'recheck-selected':await recheck([...selected]);break;case 'cancel-job':await action('cancel_job');break;case 'job-report':showJob();break;case 'back15':await seekTo((state.playback?.position||0)-15);break;case 'forward15':await seekTo((state.playback?.position||0)+15);break;case 'all-stages':stageFilter=null;selected.clear();setView('library');renderRows();break;case 'scan':case 'empty-scan':await action('scan');break;case 'refresh-tags':await action('refresh_tags');toast('Refreshing existing BPM tags; no audio rescan required.');break;case 'cancel-scan':await action('cancel_scan');break;case 'menu-toggle':$('#more-menu').hidden=!$('#more-menu').hidden;target.setAttribute('aria-expanded',String(!$('#more-menu').hidden));break;case 'clear-selection':selected.clear();renderRows();break;case 'undo':await action('undo');break;case 'train-undo':await action('undo');if(lastTrainingId&&track(lastTrainingId)&&!track(lastTrainingId).manual_stage){queue=[lastTrainingId,...queue.filter(id=>id!==lastTrainingId)];trainingId=lastTrainingId;lastTrainingId=null;renderTraining();}break;case 'apply-category':await action('labels',{ids:[...selected],stage:$('#batch-category').value});selected.clear();renderRows();break;case 'edit-bpm':openBpm([...selected]);break;case 'bpm-half':$('#bpm-value').value=Number($('#bpm-value').value)/2;break;case 'bpm-double':$('#bpm-value').value=Number($('#bpm-value').value)*2;break;case 'bpm-clear':await action('tempo',{ids:bpmIds,clear:true});$('#bpm-dialog').close();break;case 'player-play':await play(state.playing||focused);break;case 'player-stop':await action('stop');break;case 'new-batch':await newBatch();break;case 'sort-name':case 'sort-bpm':{const newSort=target.id==='sort-name'?'name':'bpm';ascending=sort===newSort?!ascending:true;sort=newSort;renderRows();break;}case 'manual-prev':manualIndex=(manualIndex+7)%8;renderManual();break;case 'manual-next':manualIndex=(manualIndex+1)%8;renderManual();break;case 'toggle-studied':{const id=manual.stages[manualIndex].id;studied=studied.includes(id)?studied.filter(s=>s!==id):[...studied,id];await action('studied',{ids:studied});renderManual();break;}case 'wheel-open':await openWheel();break;}});
$('#track-rows').addEventListener('click',event=>{if(event.target.closest('button')||event.target.matches('input'))return;const row=event.target.closest('tr');if(!row)return;focused=row.dataset.id;if(event.shiftKey&&lastRowId){const ids=visible().map(t=>t.id),a=ids.indexOf(lastRowId),b=ids.indexOf(focused);if(a>=0&&b>=0){for(const id of ids.slice(Math.min(a,b),Math.max(a,b)+1))selected.add(id);}}else{if(!event.metaKey&&!event.ctrlKey)selected.clear();selected.has(focused)?selected.delete(focused):selected.add(focused);}lastRowId=focused;renderRows();renderPlayer();});
$('#track-rows').addEventListener('dblclick',event=>{const row=event.target.closest('tr');if(row&&!event.target.closest('button'))detail(row.dataset.id);});
$('#track-rows').addEventListener('keydown',event=>{const row=event.target.closest('tr');if(event.key==='Enter'&&row){event.preventDefault();detail(row.dataset.id);}});
$('#track-rows').addEventListener('change',event=>{const id=event.target.dataset.check;if(!id)return;event.target.checked?selected.add(id):selected.delete(id);focused=id;renderRows();renderPlayer();});
$('#select-all').addEventListener('change',event=>{selected=event.target.checked?new Set(visible().map(t=>t.id)):new Set();renderRows();});
let searchTimer;$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{selected.clear();renderRows();},100);});$('#tempo-filter').addEventListener('change',()=>{selected.clear();renderRows();});
$('#bpm-form').addEventListener('submit',async event=>{event.preventDefault();if(await action('tempo',{ids:bpmIds,value:Number($('#bpm-value').value)})){$('#bpm-dialog').close();if($('#details').open)detail(focused);}});
$('#settings-form').addEventListener('submit',async event=>{event.preventDefault();if(await action('settings',{minimum:Number($('#minimum').value),maximum:Number($('#maximum').value),tempo_minimum:Number($('#preferred-minimum').value),tempo_maximum:Number($('#preferred-maximum').value),prefer_range:$('#prefer-range').checked}))$('#settings-dialog').close();});
$('#dimension-lens').addEventListener('change',applyLens);$('#transition-form').addEventListener('submit',async event=>{event.preventDefault();await refreshTransitions();});
document.addEventListener('click',event=>{if(!event.target.closest('#more-menu')&&!event.target.closest('#menu-toggle')){$('#more-menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.code==='Space'&&!event.target.closest('input,select,textarea,button')&&!document.querySelector('dialog[open]')){event.preventDefault();play(state.playing||(view==='training'?trainingId:focused));}});


function populateSettings(){for(const [id,val] of Object.entries({'average-bpm':state.average_bpm??160,'pref-low':state.tempo_minimum??140,'pref-high':state.tempo_maximum??176,'duration-low':state.minimum??90,'duration-high':state.maximum??900}))$('#'+id).value=val;$('#pref-enabled').checked=state.prefer_range!==false;$('#average-preset').value=[...$('#average-preset').options].some(o=>o.value===String(state.average_bpm))?String(state.average_bpm):'custom';}
$('#average-preset').addEventListener('change',e=>{if(e.target.value!=='custom')$('#average-bpm').value=e.target.value;});
$('#preferences-form').addEventListener('submit',async e=>{e.preventDefault();if(await action('settings',{average_bpm:Number($('#average-bpm').value),tempo_minimum:Number($('#pref-low').value),tempo_maximum:Number($('#pref-high').value),prefer_range:$('#pref-enabled').checked,minimum:Number($('#duration-low').value),maximum:Number($('#duration-high').value)}))$('#settings-saved').textContent='Saved. Recheck audio BPM to apply the new starting tempo.';});
async function recheck(ids){if(!ids.length){toast('Select tracks to recheck.',true);return;}if(ids.length>5&&!confirm(`Decode fresh audio for ${ids.length} tracks? This can take several minutes.`))return;if(await action('recheck_bpm',{ids}))toast('Audio BPM recheck started. Your manual corrections are retained.');}
function renderJob(){const j=state.job;$('#cancel-job').hidden=!j?.running;$('#job-report').hidden=!j;$('#job-report').textContent=j?`BPM ${j.done}/${j.total} · ${j.errors.length} errors`:'';$('#recheck-bpm').disabled=!!j?.running||state.scan_running;}
function showJob(){const j=state.job;if(!j)return;$('#job-details').innerHTML=`<p>${j.running?'Running':'Finished'}: ${j.done} / ${j.total} tracks.</p><p class="quiet">Fresh audio is decoded. Valid file tags and manual BPM corrections retain priority.</p><pre>${esc(j.errors.join('\n')||'No errors reported.')}</pre>`;$('#report-dialog').showModal();}
async function seekTo(position){try{state.playback=await api('seek',{seconds:position});renderPlayer();}catch(e){toast(e.message,true);}}
$('#audio-seek').addEventListener('input',e=>{seeking=true;$('#elapsed').textContent=clock(Number(e.target.value));});
$('#audio-seek').addEventListener('change',async e=>{try{await seekTo(Number(e.target.value));}finally{seeking=false;renderPlayer();}});
let playbackPolling=false;setInterval(async()=>{if(stopped||playbackPolling)return;playbackPolling=true;try{state.playback=await api('playback');renderPlayer();}catch(e){}finally{playbackPolling=false;}},500);
