  const result=await api('sets',{operation,id,...extra});
  if(token!==setLoadToken)return null;
  if(operation==='configure'||(['append_many','append_phase'].includes(operation)&&extra.criteria))setDraftCache.delete(id);
  if(result.added?.count){selectedSetIndex=result.added.last_index;inspectedCandidateId=null;inspectorPane='ratings';}
  state.set_summaries=result.sets||state.set_summaries;
  if(result.plan){activeSet=result;if(selectedSetIndex!=null&&selectedSetIndex>=result.plan.entries.length)selectedSetIndex=result.plan.entries.length?result.plan.entries.length-1:null;renderSets(result.sets);renderSet();}
  else renderSets(result.sets||[]);
  renderLibrarySetTargets(result.plan?.id);
  if(result.added)toast(result.added.count?`Added ${result.added.count} to set${result.added.duplicates?`; ${result.added.duplicates} already present`:''}.`:'These tracks are already in this set.');
  if(result.exported){showSetExport(result.exported);toast(`Exported ${result.exported.tracks} tracks in your running order.`);}
