 try{const result=await api('sets',{operation:'get',id:key,replace_index:index,details_only:true});if(token!==setLoadToken||activeSet?.plan?.id!==key||selectedSetIndex!==index)return;activeSet.analysis=result.analysis;activeSet.replacements=result.replacements;renderSetInspector();$('#set-inspector').scrollIntoView?.({behavior:'smooth',block:'start'});}catch(e){toast(e.message,true);}
