function scaledSetArc(count){
 const arc=setDraft.map(p=>({...p})),total=arc.reduce((n,p)=>n+p.tracks,0);if(count===total)return arc;
 if(!Number.isInteger(count)||count<arc.length)throw Error(`Use at least ${arc.length} tracks for these phases, or remove some phases.`);
 const weights=arc.map(p=>Math.max(0,p.tracks-1)),sum=weights.reduce((a,b)=>a+b,0)||arc.length,extra=count-arc.length;
 const shares=arc.map((p,i)=>({i,raw:extra*(weights.some(w=>w>0)?weights[i]:1)/sum}));let left=count;
 shares.forEach(x=>{arc[x.i].tracks=1+Math.floor(x.raw);left-=arc[x.i].tracks;});shares.sort((a,b)=>(b.raw%1)-(a.raw%1)||a.i-b.i);
 for(let i=0;i<left;i++)arc[shares[i].i].tracks++;
 if(arc.some(p=>p.tracks>50))throw Error('Use at most 50 tracks per phase. Add more phases for a longer set.');return arc;
}
function showSetExport(result){
 const el=$('#set-export-result');if(!el)return;
 el.innerHTML=`<div class="set-export-success"><b>Exported ${result.tracks} tracks in your edited order.</b><p>${esc(result.destination)}</p><ul>${result.files.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="quiet">Music files were not copied. Playlist import depends on your Serato version. Crates are experimental exports; nothing was installed into Serato.</p></div>`;el.scrollIntoView?.({block:'nearest',behavior:'smooth'});
}
function energyChart(positions){return targetChart([],positions);}
function targetChart(curve,positions){
 const count=Math.max(curve.length,positions.length,2),x=i=>20+i/(count-1)*560,y=e=>110-e*9;let lines=[],segment=[];
 for(const p of curve){if(Number.isFinite(p.energy))segment.push(`${x(p.position-1)},${y(p.energy)}`);else{if(segment.length)lines.push(segment.join(' '));segment=[];}}if(segment.length)lines.push(segment.join(' '));
 if(!lines.length&&!positions.some(p=>Number.isFinite(p.energy)))return '<p class="quiet">Choose an arc or analyze energy to display the curve.</p>';
 return `<p class="quiet">Cyan dashed: planned energy. Magenta: chosen tracks. Position is track order, not elapsed time.</p><svg class="energy-chart" viewBox="0 0 600 135" role="img" aria-label="Set target energy and track ratings">${lines.map(points=>`<polyline points="${points}" fill="none" stroke="#00e7ff" stroke-width="2" stroke-dasharray="6 4"/>`).join('')}${positions.filter(p=>Number.isFinite(p.energy)).map(p=>`<circle cx="${x(p.index)}" cy="${y(p.energy)}" r="4" fill="#ff007a"><title>Track ${p.index+1}: ${p.energy}</title></circle>`).join('')}<text x="20" y="130" fill="#aaa" font-size="10">Energy proxy 0–10</text></svg>`;
}
function renderPlanningCards(cards){
 lastPlanningCards=cards;const root=$('#set-phase-cards');if(!root)return;const dirty=setDraftCache.has(activeSet.plan.id),range=($('#set-mode')?.value||activeSet.plan.mode)==='range';
 root.innerHTML=cards.map(c=>`<article class="set-plan-card"><div class="set-plan-card-head"><span class="set-phase-index">${c.index+1}</span><label>Stage${range?'<b>All stages</b>':`<select data-card-stage="${c.index}" aria-label="Stage for planning card ${c.index+1}">${stageOptions(c.stage)}</select>`}</label>${range?'':`<label>Energy target<input data-card-energy="${c.index}" type="number" min="0" max="10" step=".5" aria-label="Energy target for planning card ${c.index+1}" value="${c.energy_from==null?'':Number(((c.energy_from+c.energy_to)/2).toFixed(1))}"></label>`}</div><p class="set-card-match">${c.tracks} slots · matching energy ${setNumber(c.match_min)}–${setNumber(c.match_max)}</p>${!range&&c.energy_from!==c.energy_to?`<p class="quiet">Planned ${setNumber(c.energy_from)} → ${setNumber(c.energy_to)}. Edit target to hold this section at one energy.</p>`:''}<p class="quiet">${c.matching_count} matches · ${c.unused_count} unused${c.recycled?' · All remaining matches have been shown':''}</p><button class="text-button" data-card-more="${c.index}">More suggestions ↻</button><div class="phase-track-matches">${c.rows.map(t=>`<div class="phase-track-match"><button class="phase-track-name" data-card-inspect="${esc(t.id)}" data-card-index="${c.index}">${esc(t.name)}</button><small>${setNumber(t.bpm)} BPM · ${esc(t.camelot||'—')} · energy ${setNumber(t.energy)}</small><button class="text-button" data-play="${esc(t.id)}">▶ Preview</button><button class="small-secondary" data-phase-use="${esc(t.id)}" data-phase-index="${c.index}">Add to set</button></div>`).join('')||`<p class="quiet">${c.elsewhere?'Other matches are shown in another section.':c.unused_count?'No new matches on this page. Use More suggestions.':c.matching_count?'All matching tracks are already in your set.':'No reachable tracks fit this stage and energy band. Adjust the card or analyze more music.'}</p>`}</div></article>`).join('');
}
function schedulePhasePreview(){clearTimeout(phasePreviewTimer);phasePreviewTimer=setTimeout(previewPlanningCards,300);}
async function previewPlanningCards(){
 if(!activeSet?.plan?.id||!$('#set-config-form'))return;const token=++phasePreviewToken,key=activeSet.plan.id;
 try{const config=setConfigValues();if(config.mode==='arc')config.arc=scaledSetArc(config.count);const result=await api('sets',{operation:'preview',id:key,...config});if(token!==phasePreviewToken||key!==activeSet?.plan?.id)return;renderPlanningCards(result.phase_cards);if($('#phase-preview-note'))$('#phase-preview-note').textContent=result.source_count===0?'No analyzed tracks in these folders yet. Scan a folder first.':'Preview of your criteria. Add to set saves these criteria and adds the chosen track; Generate set replaces the whole order.';}catch(e){if($('#phase-preview-note'))$('#phase-preview-note').textContent='Complete valid stage, BPM and energy criteria to preview matches.';}
}
$('#saved-sets').addEventListener('change',async e=>{if(!e.target.value)return;selectedSetIndex=0;await setRequest('get',{id:e.target.value,replace_index:0});});
$('#set-workspace').addEventListener('submit',async e=>{
 if(e.target.id!=='set-config-form')return;e.preventDefault();
 try{const config=setConfigValues();if(config.mode==='arc')config.arc=scaledSetArc(config.count);if(activeSet.plan.entries.length&&!confirm('Rebuild this running order from the chosen criteria? You can Undo this edit.'))return;selectedSetIndex=0;await setRequest('configure',{...config,replace_index:0});}catch(e){toast(e.message,true);}
});
$('#set-workspace').addEventListener('input',e=>{if(e.target.closest('#set-config-form'))rememberSetDraft();});
$('#set-workspace').addEventListener('change',async e=>{
 const t=e.target;
 if(t.dataset.cardStage!==undefined){setDraft[Number(t.dataset.cardStage)].stage=t.value;$('#arc-preset').value='custom';renderPhases();rememberSetDraft();}
 if(t.dataset.cardEnergy!==undefined){const phase=setDraft[Number(t.dataset.cardEnergy)];phase.energy_from=phase.energy_to=Number(t.value);$('#arc-preset').value='custom';renderPhases();rememberSetDraft();}
 if(t.id==='arc-preset'&&arcPresets[t.value]){setDraft=arcPresets[t.value].phases.map(p=>({...p}));$('#set-mode').value='arc';$('#set-track-count').value=setDraft.reduce((n,p)=>n+p.tracks,0);renderPhases();}
 if(t.dataset.phaseStage!==undefined)setDraft[Number(t.dataset.phaseStage)].stage=t.value;
 for(const [attr,key] of [['phaseFrom','energy_from'],['phaseTo','energy_to']])if(t.dataset[attr]!==undefined){const p=setDraft[Number(t.dataset[attr])];if(t.value==='')delete p[key];else p[key]=Number(t.value);$('#arc-preset').value='custom';}
 if(t.dataset.phaseCount!==undefined){setDraft[Number(t.dataset.phaseCount)].tracks=Number(t.value);$('#set-track-count').value=setDraft.reduce((n,p)=>n+p.tracks,0);$('#arc-preset').value='custom';}
 if(t.closest('#set-config-form'))rememberSetDraft();
 if(t.dataset.entryStage!==undefined)await setRequest('edit',{index:Number(t.dataset.entryStage),stage:t.value,...selectedExtra()});
 if(t.dataset.entryRating!==undefined)await setRequest('edit',{index:Number(t.dataset.entryRating),rating:t.value,...selectedExtra()});
});
document.addEventListener('click',async e=>{
 const t=e.target.closest('button');if(!t)return;

 if(t.id==='choose-set-source'){
  try{const result=await api('sets',{operation:'pick_source',id:activeSet.plan.id});if(result.folder&&!sourceDraftFolders.includes(result.folder)){if(sourceDraftFolders.length>=20){toast('Choose at most 20 folders.',true);return;}sourceDraftFolders.push(result.folder);renderSourceFolders();rememberSetDraft();}}catch(e){toast(e.message,true);}return;
 }
 if(t.id==='all-set-sources'){sourceDraftFolders=[];renderSourceFolders();rememberSetDraft();return;}
 if(t.dataset.removeSetSource!==undefined){sourceDraftFolders.splice(Number(t.dataset.removeSetSource),1);renderSourceFolders();rememberSetDraft();return;}
 if(t.dataset.scanSetSource!==undefined){await action('scan',{root:sourceDraftFolders[Number(t.dataset.scanSetSource)]});return;}
 if(t.dataset.inspectorPane){inspectorPane=t.dataset.inspectorPane;renderSetInspector();return;}
 if(t.id==='set-back-cards'){$('#set-phase-cards').scrollIntoView?.({behavior:'smooth',block:'center'});return;}
 if(t.id==='set-back-order'){$(`[data-set-index="${selectedSetIndex}"]`)?.scrollIntoView?.({behavior:'smooth',block:'center'});return;}
 if(t.dataset.setSwapOpen!==undefined){await selectSetTrack(Number(t.dataset.setSwapOpen),'swaps');return;}
 if(t.dataset.setSelect!==undefined){await selectSetTrack(Number(t.dataset.setSelect));return;}
 if(t.dataset.cardInspect){inspectedCandidateId=t.dataset.cardInspect;inspectedCandidatePhase=Number(t.dataset.cardIndex);inspectorPane='ratings';renderSetInspector();$('#set-inspector').scrollIntoView?.({behavior:'smooth',block:'start'});return;}
 if(t.dataset.phaseUse){await addCardTrack(t.dataset.phaseUse,Number(t.dataset.phaseIndex));return;}
 if(t.dataset.inspectorAdd){await addCardTrack(t.dataset.inspectorAdd,inspectedCandidatePhase);return;}
 if(t.dataset.cardMore!==undefined){const index=Number(t.dataset.cardMore),card=lastPlanningCards.find(c=>c.index===index);await setRequest('more_suggestions',{phase_index:index,seen_ids:card?.rows.map(r=>r.id)||[]});if(setDraftCache.has(activeSet.plan.id))await previewPlanningCards();return;}
 if(t.dataset.setSwap){await setRequest('swap',{index:Number(t.dataset.swapIndex),track_id:t.dataset.setSwap,replace_index:Number(t.dataset.swapIndex)});return;}
 if(t.dataset.phaseRemove!==undefined){setDraft.splice(Number(t.dataset.phaseRemove),1);$('#arc-preset').value='custom';$('#set-track-count').value=setDraft.reduce((n,p)=>n+p.tracks,0);renderPhases();rememberSetDraft();}
 for(const [attr,offset] of [['entryUp',-1],['entryDown',1]])if(t.dataset[attr]!==undefined){const index=Number(t.dataset[attr]);await moveSetTrack(index,index+offset);return;}
 if(t.dataset.entryRemove!==undefined){await setRequest('edit',{index:Number(t.dataset.entryRemove),remove:true});return;}
 if(t.hasAttribute('data-create-set')||t.id==='new-set'){selectedSetIndex=null;inspectedCandidateId=null;setPane='arrange';inspectorPane='ratings';setDraftCache.clear();await setRequest('create',{title:'New set',auto_populate:true,preset:'journey',limits:{bpm_min:state.tempo_minimum,bpm_max:state.tempo_maximum,energy_min:0,energy_max:10},replace_index:0});return;}
 switch(t.id){
  case 'import-set':selectedSetIndex=null;await setRequest('import');break;
  case 'refresh-set':if(activeSet)await setRequest('get',selectedExtra());break;
  case 'undo-set-order':await setRequest('undo_order');break;
  case 'export-set':await setRequest('export',{format:$('#set-export-format').value,...selectedExtra()});break;
  case 'add-phase':if(setDraft.length<32){setDraft.push({stage:'Gathering',tracks:3,energy_from:3,energy_to:4});$('#arc-preset').value='custom';$('#set-track-count').value=setDraft.reduce((n,p)=>n+p.tracks,0);renderPhases();rememberSetDraft();}break;
  case 'add-full-arc':if(setDraft.length<=24){setDraft.push(...Object.keys(palette).map((stage,i)=>({stage,tracks:3,energy_from:[3,5,8,9,8,6,4,3][i],energy_to:[3,5,8,9,8,6,4,3][i]})));$('#arc-preset').value='custom';$('#set-track-count').value=setDraft.reduce((n,p)=>n+p.tracks,0);renderPhases();rememberSetDraft();}else toast('Use up to 32 phases.',true);break;
  case 'rate-set-good':if(confirm('Confirm you reviewed every handoff and found it good?'))await setRequest('rate_all',selectedExtra());break;
  case 'learn-set':await setRequest('learn',{train_categories:$('#set-category-labels').checked,...selectedExtra()});break;
  case 'unlearn-set':await setRequest('unlearn',selectedExtra());break;
 }
});
$('#set-workspace').addEventListener('click',e=>{if(e.target.closest('button,input,select,a'))return;const row=e.target.closest('[data-set-index]');if(row)selectSetTrack(Number(row.dataset.setIndex));});
$('#set-workspace').addEventListener('keydown',e=>{const row=e.target.closest('[data-set-index]');if(row&&e.target===row&&e.key==='Enter'){e.preventDefault();selectSetTrack(Number(row.dataset.setIndex));}});
async function moveSetTrack(index,toIndex){
 const length=activeSet?.plan?.entries.length||0;if(index===toIndex||toIndex<0||toIndex>=length)return;
 const before=selectedSetIndex;if(before===index)selectedSetIndex=toIndex;else if(before!=null&&index<before&&toIndex>=before)selectedSetIndex--;else if(before!=null&&index>before&&toIndex<=before)selectedSetIndex++;
 if(!await setRequest('move',{index,to_index:toIndex,...selectedExtra()}))selectedSetIndex=before;
}
$('#set-workspace').addEventListener('dragstart',e=>{
 const row=e.target.closest('[data-set-index]');if(!row||setBusy){e.preventDefault();return;}dragSetIndex=Number(row.dataset.setIndex);row.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragSetIndex));}
});
$('#set-workspace').addEventListener('dragover',e=>{
 const row=e.target.closest('[data-set-index]');if(!row||dragSetIndex==null)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';
 $$('[data-set-index]').forEach(r=>r.classList.remove('drop-before','drop-after'));const rect=row.getBoundingClientRect(),after=e.clientY>rect.top+rect.height/2;dropSetIndex=Number(row.dataset.setIndex)+(after?1:0);row.classList.add(after?'drop-after':'drop-before');
 if(e.clientY>window.innerHeight-125)window.scrollBy?.(0,12);else if(e.clientY<85)window.scrollBy?.(0,-12);
});
$('#set-workspace').addEventListener('drop',async e=>{
 if(dragSetIndex==null||dropSetIndex==null)return;e.preventDefault();const from=dragSetIndex,to=dropSetIndex-(dropSetIndex>from?1:0);dragSetIndex=dropSetIndex=null;await moveSetTrack(from,to);
});
$('#set-workspace').addEventListener('dragend',()=>{dragSetIndex=dropSetIndex=null;$$('[data-set-index]').forEach(r=>r.classList.remove('dragging','drop-before','drop-after'));});

function renderSourceFolders(){const el=$('#set-source-folders');if(!el)return;el.innerHTML=sourceDraftFolders.length?sourceDraftFolders.map((path,i)=>`<div class="set-source-chip"><span>${esc(path)}</span><button type="button" class="text-button" data-scan-set-source="${i}">Scan folder</button><button type="button" class="text-button" data-remove-set-source="${i}" aria-label="Remove source folder">×</button></div>`).join(''):'<p class="quiet">All analyzed music in this DJ profile.</p>';}
function renderProfileControls(){
 const select=$('#dj-profile-select');if(!select||!state.profile)return;const records=state.profiles||[],signature=JSON.stringify(records.map(p=>[p.id,p.name]));
 if(select.dataset.signature!==signature||select.dataset.active!==state.profile.id){const chosen=select.value;select.innerHTML=records.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');select.value=select.dataset.active===state.profile.id&&records.some(p=>p.id===chosen)?chosen:state.profile.id;select.dataset.signature=signature;select.dataset.active=state.profile.id;}
 $('#dj-profile-current').textContent=`${state.profile.name} · ${state.stored||0} tracks · ${state.reviewed||0} labels`;
 const locked=profileBusy||state.scan_running||state.busy;$('#create-dj-profile').disabled=!!locked;$('#switch-dj-profile').disabled=!!locked;
}
async function changeDjProfile(args){
 if(profileBusy||setBusy||busy){toast('Wait for the current operation before switching profiles.',true);return;}
 if(!confirm(args.operation==='create'?'Create and switch to a separate DJ profile? Your current profile, music analysis, training and sets will be preserved.':'Switch DJ profiles? Playback stops; current data are preserved.'))return;
 profileBusy=true;++profileEpoch;renderProfileControls();
 try{
  const result=await api('profiles',args);state={...state,...result};state.revision=-1;selected.clear();focused=null;activeSet=null;lastPlanningCards=[];setDraftCache.clear();selectedSetIndex=null;inspectedCandidateId=null;queue=[];trainingId=null;lastTrainingId=null;transitionSource=null;bpmIds=[];manual=null;studied=[];sourceDraftFolders=[];clearTimeout(phasePreviewTimer);++phasePreviewToken;++setLoadToken;
  $$('dialog[open]').forEach(d=>d.close());renderSets([]);$('#set-workspace').innerHTML='';$('#library-set-target').innerHTML='<option value="__new__">＋ New set…</option>';await refresh();populateSettings();renderProfileControls();toast(`Switched to ${state.profile.name}. ${state.stored?'Analyzed music is ready; training and sets are separate.':'Start with Scan music to analyze a fresh library.'}`);
 }catch(e){toast(e.message,true);}finally{profileBusy=false;renderProfileControls();}
}
$('#dj-profile-create-form').addEventListener('submit',async e=>{e.preventDefault();await changeDjProfile({operation:'create',name:$('#dj-profile-name').value,reuse_analysis:$('#dj-profile-start').value==='reuse'});});
$('#switch-dj-profile').addEventListener('click',()=>changeDjProfile({operation:'switch',id:$('#dj-profile-select').value}));
$('#profile-scan').addEventListener('click',async()=>{setView('library');await action('scan');});
async function addCardTrack(id,phaseIndex){
 try{const card=lastPlanningCards.find(c=>c.index===phaseIndex),criteria=setDraftCache.has(activeSet.plan.id)?setConfigValues():undefined;if(criteria?.mode==='arc')criteria.arc=scaledSetArc(criteria.count);await setRequest(phaseIndex==null?'append_many':'append_phase',{ids:[id],phase_index:phaseIndex,seen_ids:card?.rows.map(r=>r.id)||[],...(criteria?{criteria}:{})});}catch(e){toast(e.message,true);}
}
function renderLibrarySetTargets(preferred){
 const el=$('#library-set-target');if(!el)return;const summaries=state.set_summaries||[],current=preferred||el.value||activeSet?.plan?.id||'';
 el.innerHTML=summaries.map(s=>`<option value="${s.id}" ${s.id===current?'selected':''}>${esc(s.title)} · ${s.tracks} tracks</option>`).join('')+'<option value="__new__">＋ New set…</option>';
 if(current==='__new__'||!summaries.length)el.value='__new__';else if(summaries.some(s=>s.id===current))el.value=current;
}
async function addLibraryTracks(ids){
 if(!ids.length){toast('Select tracks to add.',true);return;}
 const destination=$('#library-set-target').value;
 if(destination==='__new__'||!destination){libraryAddIds=ids;$('#library-new-set-title').value=stageFilter?stageFilter+' selection':'Library selection';$('#library-set-context').textContent=`Add ${ids.length} track${ids.length===1?'':'s'} together in the displayed order.`;$('#library-set-dialog').showModal();return;}
 const result=await setRequest('append_many',{id:destination,ids});if(result){selected.clear();renderRows();}
}
$('#library-set-form').addEventListener('submit',async e=>{e.preventDefault();const result=await setRequest('append_many',{id:null,ids:libraryAddIds,title:$('#library-new-set-title').value});if(result){$('#library-set-dialog').close();selected.clear();renderRows();}});
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.libraryAdd){await addLibraryTracks([t.dataset.libraryAdd]);return;}if(t.id==='add-selected-to-set'){await addLibraryTracks(visible().filter(t=>selected.has(t.id)).map(t=>t.id));return;}if(t.id==='add-visible-to-set'){await addLibraryTracks(visible().map(t=>t.id));return;}});
refresh();pollTimer=setInterval(refresh,1500);
